custom_css:
/*====================================
   INDEX
====================================*/

/*Replace normal → url("image link")*/

.welcomePanel .welcomeHeaderLogo {
    content: normal !important;
}

/*====================================
   FUNCTION PANEL & Slider + Checkbox
====================================*/

/* Replace none → hex colour / url("image link") */

:root {
    /* Function Panel BG */
    --function-bg: none;
    --function-overlay: rgba(15, 15, 18, 0.50);

    /* slider handle */
    --function-slider-icon: none;    
    /* slider track colour (white if none) */
    --function-slider-track: none;
    /* ticked checkbox */
    --function-checkbox-icon: none;
 }

/*====================================
   CUSTOM TOP-BAR & Input Area ICONS
====================================*/

/* Replace none → url("image link") */

:root {
    /* TOP BAR */

    /* Preset */
    --topbar-icon-preset: none;

    /* Connection Profile */
    --topbar-icon-api: none;

    /* Advanced Formatting */
    --topbar-icon-formatting: none;

    /* Worlds /Lorebooks */
    --topbar-icon-worldinfo: none;

    /* User Settings */
    --topbar-icon-settings: none;

    /* Backgrounds */
    --topbar-icon-backgrounds: none;

    /* Extensions */
    --topbar-icon-extensions: none;

    /* Persona Management */
    --topbar-icon-persona: none;

    /* Characters */
    --topbar-icon-characters: none;

    /* INPUT AREA */

    /* Options */
    --input-icon-options: none;

    /* Extensions */
    --input-icon-extensions: none;

    /* Impersonate */
    --input-icon-impersonate: none;

    /* Send */
    --input-icon-send: none;

    /* Stop */
    --input-icon-stop: none;

    /* space between the buttons (12px if none) */
    --input-icon-gap: none;
}
